mapper.select:
SELECT id, user_id, book_id, created_at
FROM favorite
WHERE user_id = #{userId} AND book_id = #{bookId}

mapper.delete:
DELETE FROM favorite
WHERE book_id = #{fromBookId}
  AND user_id IN (
    SELECT user_id FROM (
        SELECT user_id FROM favorite WHERE book_id = #{toBookId}
    ) AS tmp
  )
